        dy = b.y1 - a.y2;
    } else if (b.y2 < a.y1) {
        dy = a.y1 - b.y2;
    }

    return dx + dy;
}

int main() {
    long long xi, yi, xf, yf;
    if (scanf("%lld %lld %lld %lld", &xi, &yi, &xf, &yf) != 4) {
        return 0;
    }

