        rects[i + 2] = (Rect){x1, y1, x2, y2};
    }

    int total_nodes = n + 2;

    for (int i = 0; i < total_nodes; i++) {
        dist[i] = INF;
        visited[i] = 0;
    }

    dist[0] = 0;

    for (int i = 0; i < total_nodes; i++) {
        int u = -1;
        long long min_d = INF;

        for (int j = 0; j < total_nodes; j++) {
            if (!visited[j] && dist[j] < min_d) {
                min_d = dist[j];
                u = j;
            }
        }

        if (u == -1 || u == 1) {
            break;
        }

        visited[u] = 1;

        for (int v = 0; v < total_nodes; v++) {
            if (!visited[v]) {
                long long d = calc_dist(rects[u], rects[v]);
                if (dist[u] + d < dist[v]) {
                    dist[v] = dist[u] + d;
                }
            }
        }
    }

    printf("%lld\n", dist[1]);

    return 0;
}
